WITH latest_stages AS (SELECT symbol, stage, stage_score, rsi FROM scores.stage_snapshots WHERE snapshot_date = (SELECT MAX(snapshot_date) FROM scores.stage_snapshots)),
event_results AS (SELECT ce.symbol, ce.event_type, ce.event_date, ra.verdict, ra.growth_yoy_revenue_pct FROM signals.corporate_events AS ce JOIN scores.results_analysis AS ra ON ce.symbol = ra.symbol WHERE ce.event_date >= CURRENT_DATE - INTERVAL '3 months')
SELECT er.symbol, er.event_type, er.event_date, er.verdict, er.growth_yoy_revenue_pct, ls.stage, ls.stage_score, ls.rsi FROM event_results AS er JOIN latest_stages AS ls ON er.symbol = ls.symbol WHERE er.verdict IN ('beat', 'inline', 'miss') LIMIT 50;
